mapper.select:
SELECT * FROM biz_info
WHERE receiver_id = #{otherId} AND receiver_type = 1
AND created_time >= #{joinTime}
AND (info_status != 3 OR sender_id = #{userId}) AND (info_status != 4 OR sender_id != #{userId})
WHERE ((receiver_id = #{userId} AND sender_id = #{otherId}) OR (sender_id = #{userId} AND receiver_id = #{otherId})) AND receiver_type = 0 AND (info_status != 3 OR sender_id = #{userId}) AND (info_status != 4 OR sender_id != #{userId})
AND info_id < #{lastInfoId}
ORDER BY info_id DESC LIMIT #{pageSize}
